use crate::embedding::Embedding;
use crate::layer_norm::LayerNorm;
use crate::linear::Linear;
use crate::moba_block::{MobaBlock,MobaBlockState};
use crate::model_backward::{BackwardBlockKind,ModelBackwardTape};
use crate::rwkv_block::{RwkvBlock,RwkvBlockState};
use ndarray::{Array1,Array2};
#[derive(Clone,Debug)]pub struct RwkvModelConfig{pub vocab_size:usize,pub n_embd:usize,pub n_layer:usize,pub head_size:usize,pub head_size_divisor:usize,pub n_moba_layer:usize,pub moba_chunk_size:usize,pub moba_topk:usize,pub is_moe:bool,pub num_experts:usize,pub num_experts_per_tok:usize,pub qat_3bit:bool,pub qat_bits:u8}
impl RwkvModelConfig{pub fn new(vocab_size:usize,n_embd:usize,n_layer:usize,head_size:usize)->Self{assert!(vocab_size>0);assert!(n_layer>0);assert!(head_size>0);assert_eq!(n_embd%head_size,0);Self{vocab_size,n_embd,n_layer,head_size,head_size_divisor:8,n_moba_layer:0,moba_chunk_size:512,moba_topk:4,is_moe:false,num_experts:1,num_experts_per_tok:1,qat_3bit:false,qat_bits:0}}pub fn n_head(&self)->usize{self.n_embd/self.head_size}pub fn with_moba(mut self,n:usize,c:usize,k:usize)->Self{assert!(n<self.n_layer);assert!(c>0);self.n_moba_layer=n;self.moba_chunk_size=c;self.moba_topk=k;self}pub fn with_moe(mut self,on:bool,e:usize,k:usize)->Self{if on{assert!(e>0&&k>0&&k<=e)}else{assert_eq!(e,1);assert_eq!(k,1)}self.is_moe=on;self.num_experts=e;self.num_experts_per_tok=k;self}pub fn with_qat_3bit(mut self,on:bool)->Self{self.qat_3bit=on;self.qat_bits=if on{3}else{0};self}pub fn with_qat_bits(mut self,bits:u8)->Self{assert!(matches!(bits,0|2|3|4|8));self.qat_bits=bits;self.qat_3bit=bits==3;self}pub fn effective_qat_bits(&self)->u8{if self.qat_3bit{3}else{self.qat_bits}}}
#[derive(Clone,Copy)]enum BlockKind{Rwkv(usize),Moba(usize)}
pub struct RwkvModelState{pub rwkv_blocks:Vec<RwkvBlockState>,pub moba_blocks:Vec<MobaBlockState>,pub v_first:Option<Array2<f32>>}
pub struct RwkvModel{pub config:RwkvModelConfig,pub embedding:Embedding,pub rwkv_blocks:Vec<RwkvBlock>,pub moba_blocks:Vec<MobaBlock>,order:Vec<BlockKind>,pub ln_out:LayerNorm,pub head:Linear}
impl RwkvModel{pub fn new(config:RwkvModelConfig,seed:u64)->Self{assert!(matches!(config.effective_qat_bits(),0|2|3|4|8));let embedding=Embedding::new(config.vocab_size,config.n_embd,seed^0x454d_4245_4444_494e);let nr=config.n_layer-config.n_moba_layer;let rwkv_blocks=(0..nr).map(|i|RwkvBlock::new_with_moe_and_qat(config.n_embd,config.n_head(),i,config.n_layer,config.is_moe,config.num_experts,config.num_experts_per_tok,seed^(i as u64).wrapping_mul(0x9e37_79b9_7f4a_7c15),config.effective_qat_bits())).collect();let moba_blocks=(0..config.n_moba_layer).map(|i|MobaBlock::new(config.n_embd,config.head_size,config.moba_chunk_size,config.moba_topk,nr+i,config.n_layer)).collect();let mut order=Vec::with_capacity(config.n_layer);let interval=if config.n_moba_layer==0{nr}else{(nr/config.n_moba_layer).max(1)};let mut ri=0;for m in 0..config.n_moba_layer{let take=if m+1<config.n_moba_layer{interval}else{nr-ri};for k in 0..take{order.push(BlockKind::Rwkv(ri+k));}ri+=take;order.push(BlockKind::Moba(m));}while ri<nr{order.push(BlockKind::Rwkv(ri));ri+=1;}Self{config:config.clone(),embedding,rwkv_blocks,moba_blocks,order,ln_out:LayerNorm::new(config.n_embd,1e-5),head:Linear::new_no_bias(config.n_embd,config.vocab_size)}}pub fn load_safetensors(&mut self,p:impl AsRef<std::path::Path>)->Result<(),String>{crate::model_loader::load_model_safetensors(self,p)}pub fn forward(&self,t:&[usize],s:Option<&RwkvModelState>)->(Array2<f32>,RwkvModelState){let(y,s,_)=self.forward_internal(t,s,None);(y,s)}pub fn forward_with_tape(&self,t:&[usize])->(Array2<f32>,ModelBackwardTape){self.forward_with_state_and_tape(t,None)}pub fn forward_with_state_and_tape(&self,t:&[usize],s:Option<&RwkvModelState>)->(Array2<f32>,ModelBackwardTape){let(y,tp,_)=self.forward_with_tape_and_state(t,s);(y,tp)}pub fn forward_with_tape_and_state(&self,t:&[usize],s:Option<&RwkvModelState>)->(Array2<f32>,ModelBackwardTape,RwkvModelState){let order=self.order.iter().map(|k|match*k{BlockKind::Rwkv(i)=>BackwardBlockKind::Rwkv(i),BlockKind::Moba(i)=>BackwardBlockKind::Moba(i)}).collect();let mut tp=ModelBackwardTape::new(order);let(y,ns,_)=self.forward_internal(t,s,Some(&mut tp));(y,tp,ns)}fn forward_internal(&self,t:&[usize],s:Option<&RwkvModelState>,mut tape:Option<&mut ModelBackwardTape>)->(Array2<f32>,RwkvModelState,Array2<f32>){assert!(!t.is_empty());let mut x=self.embedding.forward(t);let mut rs=(0..self.rwkv_blocks.len()).map(|_|None).collect::<Vec<Option<RwkvBlockState>>>();let mut ms=(0..self.moba_blocks.len()).map(|_|None).collect::<Vec<Option<MobaBlockState>>>();let mut vf=s.and_then(|x|x.v_first.clone());for k in &self.order{let input=x.clone();match*k{BlockKind::Rwkv(i)=>{let st=s.and_then(|x|x.rwkv_blocks.get(i));if let Some(tp)=tape.as_deref_mut(){let(y,ns,bt)=self.rwkv_blocks[i].forward_with_full_tape(&x,st,vf.as_ref());vf=ns.v_first.clone();x=y;rs[i]=Some(ns);tp.record_block(input,x.clone());tp.record_rwkv_tape(bt)}else{let(y,ns)=self.rwkv_blocks[i].forward(&x,st,vf.as_ref());vf=ns.v_first.clone();x=y;rs[i]=Some(ns)}}BlockKind::Moba(i)=>{let st=s.and_then(|x|x.moba_blocks.get(i));if let Some(tp)=tape.as_deref_mut(){let(y,ns,bt)=self.moba_blocks[i].forward_with_tape(&x,st);x=y;ms[i]=Some(ns);tp.record_block(input,x.clone());tp.record_moba_tape(bt)}else{let(y,ns)=self.moba_blocks[i].forward(&x,st);x=y;ms[i]=Some(ns)}}}}let rs=rs.into_iter().map(Option::unwrap).collect();let ms=ms.into_iter().map(Option::unwrap).collect();let li=x.clone();x=self.ln_out.forward(&x);let n=x.clone();let logits=self.head.forward(&x);if let Some(tp)=tape{tp.record_head(li,n,logits.clone())}(logits,RwkvModelState{rwkv_blocks:rs,moba_blocks:ms,v_first:vf},x)}pub fn parameter_count(&self)->usize{self.embedding.parameter_count()+self.rwkv_blocks.iter().map(RwkvBlock::parameter_count).sum::<usize>()+self.moba_blocks.iter().map(MobaBlock::parameter_count).sum::<usize>()+self.ln_out.weight.len()+self.ln_out.bias.len()+self.head.parameter_count()}pub fn argmax(x:&Array2<f32>)->Array1<usize>{let mut r=Array1::zeros(x.nrows());for i in 0..x.nrows(){let mut bi=0;let mut bv=f32::NEG_INFINITY;for j in 0..x.ncols(){if x[[i,j]]>bv{bv=x[[i,j]];bi=j}}r[i]=bi}r}}
#[cfg(test)]mod tests{use super::*;#[test]fn qat_bit_modes_construct(){for b in[2u8,3,4,8]{let m=RwkvModel::new(RwkvModelConfig::new(32,16,2,4).with_qat_bits(b),1);assert_eq!(m.config.effective_qat_bits(),b);}}}
